"use client";

import { useId, useState, type ReactNode } from "react";
import { ArrowLeft, ArrowRight, RotateCcw } from "lucide-react";
import type { Locale, Localized } from "@/app/lib/paper3/catalog";
import {
  aStarTrace,
  backpropagationTrace,
  dijkstraTrace,
  displayNumber,
  learningCategoryTrace,
  learningScenarios,
  neuralInferenceTrace,
  regressionTrace,
  type AIVisualKind,
  type AStarFixtureId,
  type LearningScenarioId,
  type RegressionPointPreset,
  type SearchFixtureId,
  type SearchState,
  type SearchTrace,
  type TraceStep,
} from "@/app/lib/paper3/ai-models";
import { StateExplanation, StateHeading, StateTable } from "./Section15VisualPrimitives";
import styles from "./Section18AIWorkbench.module.css";

const t = (value: Localized, locale: Locale) => value[locale];
const yesNo = (value: boolean, locale: Locale) => value ? (locale === "vi" ? "Có" : "Yes") : (locale === "vi" ? "Không" : "No");
const viModelText: Readonly<Record<string, string>> = {
  "not-considered": "chưa xét", accepted: "chấp nhận", "rejected-higher": "từ chối vì cao hơn", "rejected-equal": "từ chối vì bằng nhau", "skipped-settled": "bỏ qua vì đã chốt",
  "continuous energy-use target supplied for every labelled training example": "mỗi ví dụ có mục tiêu mức dùng năng lượng liên tục",
  none: "không có", "no correct action label for each state": "không có nhãn hành động đúng cho mỗi trạng thái", "class label supplied for every robot image": "mỗi ảnh robot có nhãn lớp",
  "continuous-target": "mục tiêu liên tục", "no-target-pattern": "tìm mẫu không mục tiêu", "reward-penalty": "thưởng/phạt", "target-label": "nhãn mục tiêu",
  "predict a continuous energy-use value": "dự đoán giá trị năng lượng liên tục", "discover shopper groups with similar behaviour": "khám phá nhóm người mua có hành vi tương tự",
  "learn actions that increase cumulative reward": "học hành động tăng phần thưởng tích lũy", "predict the robot class for a new image": "dự đoán lớp robot của ảnh mới",
  positive: "dương", negative: "âm",
};
const modelText = (value: string, locale: Locale) => locale === "vi" ? (viModelText[value] ?? value) : value;

function SelectField({ label, value, onChange, children, scenario = false }: { readonly label: string; readonly value: string | number; readonly onChange: (value: string) => void; readonly children: ReactNode; readonly scenario?: boolean }) {
  const id = useId();
  return <div className={styles.field}><label htmlFor={id}>{label}</label><select id={id} value={value} data-ai-scenario={scenario || undefined} onChange={event => onChange(event.target.value)}>{children}</select></div>;
}

function AIStateControls<S>({ steps, index, onChange, onReset, locale }: { readonly steps: readonly TraceStep<S>[]; readonly index: number; readonly onChange: (index: number) => void; readonly onReset: () => void; readonly locale: Locale }) {
  const jumpId = useId();
  return <div className={styles.controls}>
    <button type="button" data-ai-previous disabled={index === 0} onClick={() => onChange(index - 1)}><ArrowLeft size={16} aria-hidden="true" />{locale === "vi" ? "Bước trước" : "Previous"}</button>
    <button type="button" data-ai-next disabled={index === steps.length - 1} onClick={() => onChange(index + 1)}>{locale === "vi" ? "Bước tiếp" : "Next"}<ArrowRight size={16} aria-hidden="true" /></button>
    <button type="button" data-ai-reset onClick={onReset}><RotateCcw size={16} aria-hidden="true" />{locale === "vi" ? "Đặt lại" : "Reset"}</button>
    <div className={styles.field}><label htmlFor={jumpId}>{locale === "vi" ? "Chuyển tới bước" : "Jump to step"}</label><select id={jumpId} data-ai-jump value={index} onChange={event => onChange(Number(event.target.value))}>{steps.map((step, position) => <option key={step.id} value={position}>{position + 1}. {t(step.title, locale)}</option>)}</select></div>
  </div>;
}

function Boundary({ children, locale }: { readonly children: ReactNode; readonly locale: Locale }) {
  return <aside className={styles.boundary}><strong>{locale === "vi" ? "Giới hạn mô hình" : "Model boundary"}</strong><span>{children}</span></aside>;
}

function Legend({ items, locale }: { readonly items: readonly { state: string; en: string; vi: string }[]; readonly locale: Locale }) {
  return <div className={styles.legend} aria-label={locale === "vi" ? "Chú giải trạng thái" : "State legend"}>{items.map(item => <span key={item.state} data-state={item.state}><i aria-hidden="true" />{locale === "vi" ? item.vi : item.en}</span>)}</div>;
}

function Frame<S>({ steps, index, setIndex, reset, locale, digest, children }: { readonly steps: readonly TraceStep<S>[]; readonly index: number; readonly setIndex: (value: number) => void; readonly reset: () => void; readonly locale: Locale; readonly digest: (value: S) => ReactNode; readonly children: (step: TraceStep<S>) => ReactNode }) {
  const step = steps[index] ?? steps[0];
  return <div className={styles.body} data-ai-step={step.id}>
    <StateHeading step={step} index={index} count={steps.length} locale={locale} />
    <AIStateControls steps={steps} index={index} onChange={setIndex} onReset={reset} locale={locale} />
    <div className={styles.ruleStrip}><span data-ai-rule={step.event}><b>{locale === "vi" ? "Quy tắc đang áp dụng" : "Rule being applied"}</b>{t(step.action, locale)}</span><span data-ai-outcome={step.id}><b>{locale === "vi" ? "Thay đổi / kết quả" : "Change / outcome"}</b>{t(step.outcome, locale)}</span></div>
    <div className={styles.stateView} data-ai-state={step.id}>{children(step)}</div>
    <StateExplanation step={step} locale={locale} />
    <StateTable steps={steps} selectedId={step.id} before={item => digest(item.before)} after={item => digest(item.after)} locale={locale} />
  </div>;
}

const searchDigest = (state: SearchState, astar: boolean, locale: Locale) => {
  const selected = state.currentNodeId ?? "—";
  const waiting = astar ? state.openIds.join(", ") || "—" : state.frontierIds.join(", ") || "—";
  const done = astar ? state.closedIds.join(", ") || "—" : state.settledIds.join(", ") || "—";
  const scoreSource = astar ? state.gScores : state.distances;
  const scores = Object.keys(scoreSource).sort().map(id => `${id}:${displayNumber(scoreSource[id])}`).join(",");
  const predecessors = Object.keys(state.predecessors).sort().map(id => `${id}:${state.predecessors[id] ?? "—"}`).join(",");
  return `${locale === "vi" ? "hiện tại" : "current"}=${selected}; ${astar ? "open" : "frontier"}=${waiting}; ${astar ? "closed" : "settled"}=${done}; ${astar ? "g" : "d"}={${scores}}; predecessor={${predecessors}}; ${locale === "vi" ? "quyết định" : "decision"}=${modelText(state.candidateDecision, locale)}`;
};

function GraphFigure({ trace, state, locale, astar }: { readonly trace: SearchTrace; readonly state: SearchState; readonly locale: Locale; readonly astar: boolean }) {
  const titleId = useId(), descId = useId();
  const fixture = trace.fixture;
  const pathEdges = new Set(state.path.slice(1).map((node, index) => {
    const previous = state.path[index];
    return fixture.edges.find(edge => (edge.from === previous && edge.to === node) || (!fixture.directed && edge.to === previous && edge.from === node))?.id;
  }).filter(Boolean));
  const nodeState = (id: string) => state.currentNodeId === id ? "current" : state.path.includes(id) ? "active" : (astar ? state.closedIds : state.settledIds).includes(id) ? (astar ? "closed" : "settled") : (astar ? state.openIds : state.frontierIds).includes(id) ? (astar ? "open" : "frontier") : "unvisited";
  const score = (id: string) => astar ? `g ${displayNumber(state.gScores[id])} · h ${displayNumber(state.hScores[id])} · f ${displayNumber(state.fScores[id])}` : `d ${displayNumber(state.distances[id])}`;
  const candidateEdge = fixture.edges.find(edge => edge.id === state.candidateEdgeId);
  const candidateTarget = candidateEdge && state.currentNodeId ? (candidateEdge.from === state.currentNodeId ? candidateEdge.to : candidateEdge.from) : candidateEdge ? candidateEdge.to : null;
  const candidateDescription = candidateEdge ? `${locale === "vi" ? "Cạnh ứng viên" : "Candidate edge"} ${candidateEdge.id} ${candidateEdge.from}–${candidateEdge.to}; ${locale === "vi" ? "quyết định" : "decision"}: ${modelText(state.candidateDecision, locale)}; ${candidateTarget ? `${astar ? "g" : "d"}(${candidateTarget})=${displayNumber((astar ? state.gScores : state.distances)[candidateTarget])}, predecessor=${state.predecessors[candidateTarget] ?? "—"}` : ""}.` : "";
  const description = `${t(fixture.title, locale)}. ${locale === "vi" ? "Nút hiện tại" : "Current node"}: ${state.currentNodeId ?? "—"}. ${astar ? "Open" : "Frontier"}: ${(astar ? state.openIds : state.frontierIds).join(", ") || "—"}. ${astar ? "Closed" : "Settled"}: ${(astar ? state.closedIds : state.settledIds).join(", ") || "—"}. ${candidateDescription}`;
  return <figure className={styles.graphFigure}>
    <svg viewBox="0 0 100 100" role="img" aria-labelledby={`${titleId} ${descId}`} preserveAspectRatio="xMidYMid meet">
      <title id={titleId}>{t(fixture.title, locale)}</title><desc id={descId}>{description}</desc>
      {fixture.edges.map(edge => {
        const from = fixture.nodes.find(node => node.id === edge.from)!; const to = fixture.nodes.find(node => node.id === edge.to)!;
        const active = state.candidateEdgeId === edge.id;
        return <g key={edge.id} data-edge-id={edge.id} data-edge-state={pathEdges.has(edge.id) ? "path" : active ? state.candidateDecision : "idle"}>
          <line x1={from.x} y1={from.y} x2={to.x} y2={to.y} />
          <text x={(from.x + to.x) / 2} y={(from.y + to.y) / 2 - 2}>{edge.weight}</text>
        </g>;
      })}
      {fixture.nodes.map(node => <g key={node.id} data-node-id={node.id} data-state={nodeState(node.id)} transform={`translate(${node.x} ${node.y})`}>
        <circle r="8" /><text className={styles.nodeId} y="-1">{node.id}</text><text className={styles.nodeScore} y="4">{score(node.id)}</text>
        {(node.id === fixture.startId || node.id === fixture.goalId) && <text className={styles.nodeRole} y="12">{node.id === fixture.startId ? (locale === "vi" ? "Bắt đầu" : "Start") : (locale === "vi" ? "Đích" : "Goal")}</text>}
      </g>)}
    </svg>
    <figcaption>{description}</figcaption>
  </figure>;
}

function SearchEvidence({ trace, step, locale, astar }: { readonly trace: SearchTrace; readonly step: TraceStep<SearchState>; readonly locale: Locale; readonly astar: boolean }) {
  const state = step.after; const edge = trace.fixture.edges.find(item => item.id === state.candidateEdgeId);
  let arithmetic = locale === "vi" ? "Chưa xét cạnh ở bước này." : "No edge is being considered at this step.";
  let update = locale === "vi" ? "Không có cập nhật khoảng cách hay predecessor ở bước này." : "No distance or predecessor update at this step.";
  if (edge && step.before.currentNodeId) {
    const current = step.before.currentNodeId; const target = edge.from === current ? edge.to : edge.from;
    const base = astar ? step.before.gScores[current] : step.before.distances[current];
    const candidate = base === null ? null : base + edge.weight;
    arithmetic = astar ? `g(${current}) ${displayNumber(base)} + ${edge.weight} = ${displayNumber(candidate)}; h(${target}) ${displayNumber(state.hScores[target])}; f = ${displayNumber(candidate === null ? null : candidate + (state.hScores[target] ?? 0))}.` : `d(${current}) ${displayNumber(base)} + ${edge.weight} = ${displayNumber(candidate)} → d(${target}) ${displayNumber(state.distances[target])}.`;
    const beforeValue = astar ? step.before.gScores[target] : step.before.distances[target];
    const afterValue = astar ? state.gScores[target] : state.distances[target];
    update = `${astar ? "g" : "d"}(${target}): ${displayNumber(beforeValue)} → ${displayNumber(afterValue)}; predecessor(${target}): ${step.before.predecessors[target] ?? "—"} → ${state.predecessors[target] ?? "—"}.`;
  }
  return <div className={styles.evidence}>
    <div><span>{locale === "vi" ? "Quy tắc hiện tại" : "Current rule"}</span><strong>{t(step.title, locale)}</strong></div>
    <div><span>{locale === "vi" ? "Phép tính ứng viên" : "Candidate calculation"}</span><strong>{arithmetic}</strong></div>
    <div data-search-update><span>{locale === "vi" ? "Trước → sau" : "Before → after"}</span><strong>{update}</strong></div>
    <div data-decision={state.candidateDecision}><span>{locale === "vi" ? "Quyết định" : "Decision"}</span><strong>{modelText(state.candidateDecision, locale)}</strong></div>
    <div><span>{locale === "vi" ? "Thứ tự đã chọn" : "Selected order"}</span><strong>{state.selectedOrder.join(" → ") || "—"}</strong></div>
    <div><span>{locale === "vi" ? "Tuyến / kết quả" : "Route / result"}</span><strong>{state.path.length ? `${state.path.join(" → ")} · ${locale === "vi" ? "chi phí" : "cost"} ${state.totalCost}` : state.terminalStatus === "no-path" ? (locale === "vi" ? "Không có đường đi" : "No path") : "—"}</strong></div>
  </div>;
}

function SearchTables({ trace, state, locale, astar }: { readonly trace: SearchTrace; readonly state: SearchState; readonly locale: Locale; readonly astar: boolean }) {
  return <details className={styles.readback}><summary>{locale === "vi" ? "Đọc đồ thị dạng bảng" : "Read graph as tables"}</summary><div className={styles.tableScroll} role="region" tabIndex={0} aria-label={locale === "vi" ? "Dữ liệu nút và cạnh" : "Node and edge data"}>
    <table><caption>{locale === "vi" ? "Bảng nút — cùng trạng thái với đồ thị" : "Node table — the same state as the graph"}</caption><thead><tr><th>{locale === "vi" ? "Nút" : "Node"}</th>{astar ? <><th>g</th><th>h</th><th>f</th></> : <th>{locale === "vi" ? "Khoảng cách" : "Distance"}</th>}<th>Predecessor</th><th>{locale === "vi" ? "Trạng thái" : "Status"}</th></tr></thead><tbody>{trace.fixture.nodes.map(node => <tr key={node.id}><th scope="row">{node.id}</th>{astar ? <><td>{displayNumber(state.gScores[node.id])}</td><td>{displayNumber(state.hScores[node.id])}</td><td>{displayNumber(state.fScores[node.id])}</td></> : <td>{displayNumber(state.distances[node.id])}</td>}<td>{state.predecessors[node.id] ?? "—"}</td><td>{state.currentNodeId === node.id ? (locale === "vi" ? "Hiện tại" : "Current") : (astar ? state.closedIds : state.settledIds).includes(node.id) ? (astar ? "Closed" : "Settled") : (astar ? state.openIds : state.frontierIds).includes(node.id) ? (astar ? "Open" : "Frontier") : (locale === "vi" ? "Chưa thăm" : "Unvisited")}</td></tr>)}</tbody></table>
    <table><caption>{locale === "vi" ? "Bảng cạnh" : "Edge table"}</caption><thead><tr><th>ID</th><th>{locale === "vi" ? "Hai đầu" : "Endpoints"}</th><th>{locale === "vi" ? "Trọng số" : "Weight"}</th><th>{locale === "vi" ? "Quyết định hiện tại" : "Current decision"}</th></tr></thead><tbody>{trace.fixture.edges.map(edge => <tr key={edge.id}><th scope="row">{edge.id}</th><td>{edge.from}–{edge.to}</td><td>{edge.weight}</td><td>{state.candidateEdgeId === edge.id ? modelText(state.candidateDecision, locale) : "—"}</td></tr>)}</tbody></table>
  </div></details>;
}

function DijkstraWorkbench({ locale }: { readonly locale: Locale }) {
  const [scenario, setScenario] = useState<SearchFixtureId>("primary"), [index, setIndex] = useState(0), [predictionChoice, setPredictionChoice] = useState(""), [predictionRevealed, setPredictionRevealed] = useState(false); const trace = dijkstraTrace(scenario); const step = trace.steps[index] ?? trace.steps[0];
  const predictionName = useId();
  const nextSelection = trace.steps.slice(index + 1).find(item => item.event === "select-node")?.after.currentNodeId ?? null;
  const moveToStep = (value: number) => { setIndex(value); setPredictionChoice(""); setPredictionRevealed(false); };
  const reset = () => { setScenario("primary"); setIndex(0); setPredictionChoice(""); setPredictionRevealed(false); };
  return <div className={styles.workbench} data-visual-kind="dijkstra-search" data-scenario={scenario} data-result={step.after.terminalStatus ?? "pending"}>
    <div className={styles.setup}><SelectField scenario label={locale === "vi" ? "Tình huống đồ thị" : "Graph scenario"} value={scenario} onChange={value => { setScenario(value as SearchFixtureId); moveToStep(0); }}><option value="primary">{locale === "vi" ? "Đồ thị tuyến dùng chung" : "Shared route graph"}</option><option value="tie">{locale === "vi" ? "Đồng chi phí" : "Equal-cost tie"}</option><option value="unreachable">{locale === "vi" ? "Đích không kết nối" : "Disconnected goal"}</option></SelectField><div className={styles.setupFact}><b>{locale === "vi" ? "Quy tắc phá hòa" : "Tie-break"}</b><span>{locale === "vi" ? "Khoảng cách bằng nhau → ID nút tăng dần; giữ predecessor đầu tiên." : "Equal distance → ascending node ID; retain the first predecessor."}</span></div></div>
    <Boundary locale={locale}>{locale === "vi" ? "Mô hình dùng đồ thị vô hướng có trọng số không âm đã duyệt. Dijkstra chọn theo khoảng cách tích lũy, không dùng heuristic." : "This reviewed teaching model uses an undirected graph with non-negative weights. Dijkstra selects by cumulative distance and uses no heuristic."}</Boundary>
    <Legend locale={locale} items={[{ state: "unvisited", en: "Unvisited", vi: "Chưa thăm" }, { state: "frontier", en: "Frontier (F)", vi: "Frontier (F)" }, { state: "current", en: "Current", vi: "Hiện tại" }, { state: "settled", en: "Settled", vi: "Đã chốt" }, { state: "active", en: "Final path", vi: "Đường cuối" }]} />
    <Frame steps={trace.steps} index={index} setIndex={moveToStep} reset={reset} locale={locale} digest={state => searchDigest(state, false, locale)}>{current => <><fieldset className={styles.predictNext} data-dijkstra-prediction><legend>{locale === "vi" ? "Dự đoán nút nào sẽ được chọn ở lần chọn kế tiếp" : "Predict the node selected at the next selection stage"}</legend>{nextSelection ? <><div>{trace.fixture.nodes.map(node => <label key={node.id}><input type="radio" name={predictionName} value={node.id} checked={predictionChoice === node.id} onChange={() => { setPredictionChoice(node.id); setPredictionRevealed(false); }} />{node.id}</label>)}</div><button type="button" data-dijkstra-reveal disabled={!predictionChoice} onClick={() => setPredictionRevealed(true)}>{locale === "vi" ? "Mở đáp án dự đoán" : "Reveal prediction"}</button><p role="status" aria-live="polite" data-prediction-result={predictionRevealed ? predictionChoice === nextSelection ? "correct" : "incorrect" : "pending"}>{predictionRevealed ? predictionChoice === nextSelection ? (locale === "vi" ? `Đúng. Nút ${nextSelection} có working distance nhỏ nhất; nếu hòa thì dùng ID.` : `Correct. ${nextSelection} has the smallest working distance; node ID breaks a tie.`) : (locale === "vi" ? `Chưa đúng. Nút kế tiếp là ${nextSelection}; hãy so sánh toàn bộ frontier.` : `Not yet. The next node is ${nextSelection}; compare the complete frontier.`) : (locale === "vi" ? "Chọn một nút rồi mở đáp án trước khi tiếp tục." : "Choose a node, then reveal the answer before continuing.")}</p></> : <p data-prediction-result="complete">{locale === "vi" ? "Không còn giai đoạn chọn nút nào; thuật toán đã kết thúc." : "No selection stage remains; the algorithm has finished."}</p>}</fieldset><div className={styles.split}><GraphFigure trace={trace} state={current.after} locale={locale} astar={false} /><SearchEvidence trace={trace} step={current} locale={locale} astar={false} /></div><SearchTables trace={trace} state={current.after} locale={locale} astar={false} /></>}</Frame>
  </div>;
}

function AStarWorkbench({ locale }: { readonly locale: Locale }) {
  const [scenario, setScenario] = useState<AStarFixtureId>("primary"), [index, setIndex] = useState(0), [compare, setCompare] = useState(true); const trace = aStarTrace(scenario); const step = trace.steps[index] ?? trace.steps[0];
  const reset = () => { setScenario("primary"); setIndex(0); setCompare(true); };
  const dijkstra = scenario === "inadmissible" ? ["S", "A", "B", "G"] : dijkstraTrace(scenario).final.selectedOrder;
  const comparisonLength = Math.max(step.after.selectedOrder.length, dijkstra.length);
  return <div className={styles.workbench} data-visual-kind="astar-search" data-scenario={scenario} data-result={step.after.terminalStatus ?? "pending"}>
    <div className={styles.setup}><SelectField scenario label={locale === "vi" ? "Tình huống heuristic" : "Heuristic scenario"} value={scenario} onChange={value => { setScenario(value as AStarFixtureId); setIndex(0); }}><option value="primary">{locale === "vi" ? "Heuristic hữu ích" : "Helpful heuristic"}</option><option value="tie">{locale === "vi" ? "Hòa f" : "Equal f tie"}</option><option value="inadmissible">{locale === "vi" ? "Giới hạn heuristic" : "Heuristic limitation"}</option></SelectField><label className={styles.check}><input type="checkbox" checked={compare} onChange={event => setCompare(event.target.checked)} />{locale === "vi" ? "So sánh với Dijkstra" : "Compare with Dijkstra"}</label></div>
    <Boundary locale={locale}>{scenario === "inadmissible" ? (locale === "vi" ? "Heuristic cố ý ước lượng quá cao; kết quả chi phí 10 không tối ưu so với tuyến tham chiếu chi phí 6." : "The heuristic deliberately overestimates; the returned cost 10 is not optimal compared with the reference cost 6.") : (locale === "vi" ? "Trong fixture đã duyệt, A* chọn f = g + h; tuyên bố tối ưu chỉ áp dụng với các điều kiện heuristic đã nêu." : "In the reviewed fixture A* selects by f = g + h; the optimality claim only applies under the stated heuristic conditions.")}</Boundary>
    <Legend locale={locale} items={[{ state: "unvisited", en: "Unvisited", vi: "Chưa thăm" }, { state: "open", en: "Open", vi: "Open" }, { state: "current", en: "Current", vi: "Hiện tại" }, { state: "closed", en: "Closed", vi: "Closed" }, { state: "active", en: "Selected route", vi: "Tuyến đã chọn" }]} />
    <Frame steps={trace.steps} index={index} setIndex={setIndex} reset={reset} locale={locale} digest={state => searchDigest(state, true, locale)}>{current => <><div className={styles.split}><GraphFigure trace={trace} state={current.after} locale={locale} astar /><SearchEvidence trace={trace} step={current} locale={locale} astar /></div>{compare && <div className={styles.comparison}><div><span>A*</span><ol>{current.after.selectedOrder.map(node => <li key={node}>{node}</li>)}</ol></div><div><span>Dijkstra</span><ol>{dijkstra.map(node => <li key={node}>{node}</li>)}</ol></div><div className={styles.comparisonTable}><table data-astar-comparison-table><caption>{locale === "vi" ? "Thứ tự nút được chọn: A* hiện tại so với Dijkstra tham chiếu" : "Selected-node order: current A* trace versus the Dijkstra reference"}</caption><thead><tr><th>{locale === "vi" ? "Vị trí" : "Position"}</th><th>A*</th><th>Dijkstra</th></tr></thead><tbody>{Array.from({ length: comparisonLength }, (_, position) => <tr key={position}><th scope="row">{position + 1}</th><td>{current.after.selectedOrder[position] ?? "—"}</td><td>{dijkstra[position] ?? "—"}</td></tr>)}</tbody></table></div></div>}<SearchTables trace={trace} state={current.after} locale={locale} astar /></>}</Frame>
  </div>;
}

const categoryCopy: Record<string, Localized> = {
  supervised: { en: "Supervised learning", vi: "Học có giám sát" }, unsupervised: { en: "Unsupervised learning", vi: "Học không giám sát" }, reinforcement: { en: "Reinforcement learning", vi: "Học tăng cường" },
};

function LearningWorkbench({ locale }: { readonly locale: Locale }) {
  const [scenario, setScenario] = useState<LearningScenarioId>("labelled-energy-regression"), [index, setIndex] = useState(0), [choice, setChoice] = useState(""), [checked, setChecked] = useState(false); const trace = learningCategoryTrace(scenario); const current = trace.steps[index] ?? trace.steps[0];
  const reset = () => { setScenario("labelled-energy-regression"); setIndex(0); setChoice(""); setChecked(false); };
  const changeScenario = (value: string) => { setScenario(value as LearningScenarioId); setIndex(0); setChoice(""); setChecked(false); };
  const correct = choice === trace.final.expectedCategory;
  return <div className={styles.workbench} data-visual-kind="learning-categories" data-scenario={scenario} data-result={!checked ? "pending" : correct ? "correct" : "incorrect"}>
    <div className={styles.setup}><SelectField scenario label={locale === "vi" ? "Tình huống học" : "Learning scenario"} value={scenario} onChange={changeScenario}>{Object.values(learningScenarios).map(item => <option key={item.id} value={item.id}>{t(item.title, locale)}</option>)}</SelectField></div>
    <Boundary locale={locale}>{locale === "vi" ? "Phân loại dựa trên loại phản hồi có sẵn: nhãn/mục tiêu, không nhãn, hoặc thưởng/phạt sau hành động. Từ khóa trong tên tình huống không quyết định đáp án." : "Classify from the available feedback: labels/targets, no labels, or reward/penalty after action. Keywords in a scenario title do not decide the answer."}</Boundary>
    <Frame steps={trace.steps} index={index} setIndex={setIndex} reset={reset} locale={locale} digest={value => `${modelText(value.labelsOrTargets, locale)}; ${modelText(value.feedbackType, locale)}; ${modelText(value.requiredOutcome, locale)}`}>{step => <>
      <div className={styles.evidenceGrid}>
        <div data-state={index >= 0 ? "active" : "unvisited"}><span>{locale === "vi" ? "Dữ liệu huấn luyện" : "Training examples / data"}</span><strong>{t(step.after.data, locale)}</strong></div>
        <div data-state={index >= 0 ? "active" : "unvisited"}><span>{locale === "vi" ? "Nhãn / mục tiêu?" : "Labels / targets?"}</span><strong>{modelText(step.after.labelsOrTargets, locale)}</strong></div>
        <div data-state={index >= 1 ? "active" : "unvisited"}><span>{locale === "vi" ? "Tương tác môi trường?" : "Environment interaction?"}</span><strong>{yesNo(step.after.environmentInteraction, locale)}</strong></div>
        <div data-state={index >= 1 ? "active" : "unvisited"}><span>{locale === "vi" ? "Phản hồi → đầu ra" : "Feedback → required output"}</span><strong>{modelText(step.after.feedbackType, locale)} → {modelText(step.after.requiredOutcome, locale)}</strong></div>
      </div>
      <fieldset className={styles.choiceGroup}><legend>{locale === "vi" ? "Bạn chọn hình thức học nào?" : "Which learning category fits?"}</legend>{["supervised", "unsupervised", "reinforcement"].map(value => <label key={value}><input type="radio" name={`category-${scenario}`} value={value} checked={choice === value} onChange={() => { setChoice(value); setChecked(false); }} />{t(categoryCopy[value], locale)}</label>)}<button type="button" disabled={!choice} onClick={() => setChecked(true)}>{locale === "vi" ? "Kiểm tra lập luận" : "Check reasoning"}</button></fieldset>
      <div className={styles.feedback} role="status" aria-live="polite" data-feedback={checked ? correct ? "correct" : "incorrect" : "pending"}><strong>{!checked ? (locale === "vi" ? "Chưa mở đáp án" : "Not revealed") : correct ? (locale === "vi" ? "Đúng — dùng loại phản hồi quyết định." : "Correct — the feedback type decides it.") : (locale === "vi" ? `Chưa đúng. Giữ lựa chọn ${t(categoryCopy[choice], locale)}; xem lại dấu hiệu quyết định.` : `Not yet. Keep your ${t(categoryCopy[choice], locale)} choice and revisit the decisive clue.`)}</strong>{checked && <span>{t(trace.final.nearMissReason, locale)} {locale === "vi" ? "Đáp án phù hợp:" : "Expected category:"} {t(categoryCopy[trace.final.expectedCategory], locale)}.</span>}</div>
      <details className={styles.readback} data-state-fallback><summary>{locale === "vi" ? "Đọc ma trận tình huống và đáp án tham chiếu" : "Read scenario matrix and reference answers"}</summary><div className={styles.tableScroll} role="region" tabIndex={0} aria-label={locale === "vi" ? "Ma trận hình thức học" : "Learning category matrix"}><table><caption>{locale === "vi" ? "Mỗi hàng ghi rõ bằng chứng, đáp án tham chiếu và bẫy gần đúng." : "Each row names the evidence, reference answer and near miss."}</caption><thead><tr><th>{locale === "vi" ? "Tình huống" : "Scenario"}</th><th>{locale === "vi" ? "Nhãn/mục tiêu" : "Labels/targets"}</th><th>{locale === "vi" ? "Loại phản hồi" : "Feedback type"}</th><th>{locale === "vi" ? "Tương tác" : "Interaction"}</th><th>{locale === "vi" ? "Đầu ra" : "Output"}</th><th>{locale === "vi" ? "Đáp án tham chiếu" : "Reference answer"}</th><th>{locale === "vi" ? "Vì sao phương án gần đúng sai" : "Why the near miss is wrong"}</th></tr></thead><tbody>{Object.values(learningScenarios).map(item => <tr key={item.id} data-fallback-step={item.id}><th scope="row">{t(item.title, locale)}</th><td>{modelText(item.labelsOrTargets, locale)}</td><td>{modelText(item.feedbackType, locale)}</td><td>{yesNo(item.environmentInteraction, locale)}</td><td>{modelText(item.requiredOutcome, locale)}</td><td>{t(categoryCopy[item.expectedCategory], locale)}</td><td>{t(item.nearMissReason, locale)}</td></tr>)}</tbody></table></div></details>
    </>}</Frame>
  </div>;
}

function NeuralWorkbench({ locale }: { readonly locale: Locale }) {
  const [depth, setDepth] = useState<"shallow" | "deep">("shallow"), [preset, setPreset] = useState<"standard" | "alternate">("standard"), [index, setIndex] = useState(0); const trace = neuralInferenceTrace(depth, preset); const step = trace.steps[index] ?? trace.steps[0];
  const reset = () => { setDepth("shallow"); setPreset("standard"); setIndex(0); };
  const scenario = `${depth}-${preset}` as "shallow-standard" | "shallow-alternate" | "deep-standard" | "deep-alternate";
  const changeScenario = (value: string) => { const [nextDepth, nextPreset] = value.split("-") as ["shallow" | "deep", "standard" | "alternate"]; setDepth(nextDepth); setPreset(nextPreset); setIndex(0); };
  const desc = `${locale === "vi" ? `Mạng ${depth === "shallow" ? "nông" : "sâu hơn"}` : `Network ${depth}`}; ${locale === "vi" ? "các lớp hiện có" : "visible layers"}: ${step.after.layers.map(layer => `${layer.id} ${layer.values.join(",")}`).join("; ") || "—"}; ${locale === "vi" ? "kết nối trọng số cố định" : "fixed weighted connections"}: ${step.after.connections.map(connection => `${connection.fromNodeId}→${connection.toNodeId} w=${connection.weight}`).join("; ")}; ${locale === "vi" ? "dự đoán" : "prediction"}: ${displayNumber(step.after.prediction)}.`;
  return <div className={styles.workbench} data-visual-kind="neural-network" data-scenario={scenario} data-result={step.after.prediction === null ? "pending" : "prediction"}>
    <div className={styles.setup}><SelectField scenario label={locale === "vi" ? "Cấu trúc và bộ đầu vào" : "Structure and input fixture"} value={scenario} onChange={changeScenario}><option value="shallow-standard">{locale === "vi" ? "Mạng nông · chuẩn 0.8, 0.6" : "Shallow · standard 0.8, 0.6"}</option><option value="shallow-alternate">{locale === "vi" ? "Mạng nông · thay thế 0.3, 0.4" : "Shallow · alternate 0.3, 0.4"}</option><option value="deep-standard">{locale === "vi" ? "Mạng sâu hơn · chuẩn 0.8, 0.6" : "Deeper · standard 0.8, 0.6"}</option><option value="deep-alternate">{locale === "vi" ? "Mạng sâu hơn · thay thế 0.3, 0.4" : "Deeper · alternate 0.3, 0.4"}</option></SelectField><div className={styles.setupFact}><b>{locale === "vi" ? "Chế độ" : "Mode"}</b><span>{locale === "vi" ? "Suy luận: chuyển tín hiệu tiến, không đổi trọng số." : "Inference: move signals forward; do not change weights."}</span></div></div>
    <Boundary locale={locale}>{locale === "vi" ? "Đây là các nút nhân tạo với trọng số cố định trong lúc suy luận, không phải neuron sinh học hay mô hình suy nghĩ của con người. Không trọng số nào đổi trong minh họa này." : "These are artificial teaching nodes with fixed weights during inference, not biological neurons or a model of human thought. No weight changes in this visual."}</Boundary>
    <Legend locale={locale} items={[{ state: "active", en: "Active layer", vi: "Lớp đang hoạt động" }, { state: "updated", en: "Value calculated", vi: "Đã tính giá trị" }, { state: "unvisited", en: "Not reached", vi: "Chưa tới" }]} />
    <Frame steps={trace.steps} index={index} setIndex={setIndex} reset={reset} locale={locale} digest={value => `${locale === "vi" ? "độ sâu" : "depth"}=${locale === "vi" ? value.depth === "shallow" ? "nông" : "sâu hơn" : value.depth}; ${locale === "vi" ? "lớp" : "layers"}=${value.layers.map(layer => `${layer.id}:${layer.values.join(",")}`).join("|")}; ${locale === "vi" ? "kết nối" : "connections"}=${value.connections.map(connection => `${connection.id}:${connection.weight}`).join("|")}; ${locale === "vi" ? "phép tính" : "calculations"}=${value.nodeCalculations.map(item => `${item.nodeId}:${item.weightedSum}→${item.activationOutput}`).join("|")}; ${locale === "vi" ? "dự đoán" : "prediction"}=${displayNumber(value.prediction)}; ${locale === "vi" ? "trọng số thay đổi=không" : "weightsChanged=false"}`}>{current => {
      const calculatedNodes = new Set(current.after.nodeCalculations.map(item => item.nodeId));
      return <>
        <figure className={styles.networkFigure} aria-label={desc}><div className={styles.layerFlow}>{["input", ...(depth === "deep" ? ["hidden-1", "hidden-2"] : []), "output"].map((layerId, layerIndex, all) => { const layer = current.after.layers.find(item => item.id === layerId); return <div className={styles.layerUnit} key={layerId} data-state={layer ? layerIndex === current.after.layers.length - 1 ? "active" : "updated" : "unvisited"}><span>{layerId}</span><strong>{layer ? layer.values.map(displayNumber).join(" · ") : "—"}</strong>{layer && <small>{t(layer.note, locale)}</small>}{layerIndex < all.length - 1 && <i aria-hidden="true">→</i>}</div>; })}</div><figcaption>{desc}</figcaption></figure>
        <section className={styles.connectionMap} aria-label={locale === "vi" ? "Trọng số kết nối cố định" : "Fixed connection weights"}><h3>{locale === "vi" ? "Trọng số kết nối thực dùng ở lượt suy luận này" : "Connection weights used by this inference pass"}</h3><ul>{current.after.connections.map(connection => <li key={connection.id} data-connection-id={connection.id} data-state={calculatedNodes.has(connection.toNodeId) ? "updated" : "unvisited"}><code>{connection.fromNodeId}</code><span aria-hidden="true">→</span><code>{connection.toNodeId}</code><strong>w = {displayNumber(connection.weight)}</strong></li>)}</ul></section>
        <section className={styles.nodeMathGrid} aria-label={locale === "vi" ? "Phép tính theo từng nút" : "Per-node calculations"}>{current.after.nodeCalculations.length ? current.after.nodeCalculations.map(calculation => <article key={calculation.nodeId} data-neural-node={calculation.nodeId}><h3>{locale === "vi" ? "Nút" : "Node"} {calculation.nodeId}</h3><ul>{calculation.contributions.map(item => <li key={item.sourceNodeId}><code>{item.sourceNodeId}</code>: {displayNumber(item.sourceValue)} × {displayNumber(item.weight)} = <strong>{displayNumber(item.contribution)}</strong></li>)}</ul><p><span>{locale === "vi" ? "Tổng có trọng số" : "Weighted sum"}</span><strong>Σ + bias {displayNumber(calculation.bias)} = {displayNumber(calculation.weightedSum)}</strong></p><p><span>{locale === "vi" ? "Hàm kích hoạt" : "Activation"}</span><strong>{calculation.activation === "relu" ? "ReLU" : (locale === "vi" ? "đồng nhất" : "identity")}({displayNumber(calculation.weightedSum)}) = {displayNumber(calculation.activationOutput)}</strong></p></article>) : <p className={styles.pendingMath}>{locale === "vi" ? "Tiến tới lớp tiếp theo để hiện từng tích, bias, tổng và kết quả kích hoạt." : "Advance to the next layer to reveal each product, bias, weighted sum and activation output."}</p>}</section>
        <div className={styles.predictionCard} aria-live="polite"><span>{locale === "vi" ? "Đầu ra sau ngưỡng 0.5" : "Output at threshold 0.5"}</span><strong>{current.after.prediction === null ? (locale === "vi" ? "Chưa mở đáp án" : "Not revealed") : `${displayNumber(current.after.prediction)} → ${modelText(current.after.predictedClass ?? "", locale)}`}</strong><small>{locale === "vi" ? "Chế độ suy luận · trọng số không đổi" : "Inference mode · weights unchanged"}</small></div>
        <details className={styles.readback} data-state-fallback><summary>{locale === "vi" ? "Đọc trọng số và phép tính dạng bảng" : "Read weights and calculations as tables"}</summary><div className={styles.tableScroll} role="region" tabIndex={0} aria-label={locale === "vi" ? "Bảng trọng số và phép tính mạng" : "Network weight and calculation tables"}><table><caption>{locale === "vi" ? "Giá trị theo lớp" : "Values by layer"}</caption><thead><tr><th>{locale === "vi" ? "Lớp" : "Layer"}</th><th>{locale === "vi" ? "Giá trị" : "Values"}</th><th>{locale === "vi" ? "Ghi chú" : "Note"}</th></tr></thead><tbody>{current.after.layers.map(layer => <tr key={layer.id}><th scope="row">{layer.id}</th><td>{layer.values.map(displayNumber).join(", ")}</td><td>{t(layer.note, locale)}</td></tr>)}</tbody></table><table><caption>{locale === "vi" ? "Trọng số kết nối cố định" : "Fixed connection weights"}</caption><thead><tr><th>{locale === "vi" ? "Từ nút" : "From node"}</th><th>{locale === "vi" ? "Đến nút" : "To node"}</th><th>{locale === "vi" ? "Trọng số" : "Weight"}</th></tr></thead><tbody>{current.after.connections.map(connection => <tr key={connection.id}><th scope="row">{connection.fromNodeId}</th><td>{connection.toNodeId}</td><td>{displayNumber(connection.weight)}</td></tr>)}</tbody></table><table><caption>{locale === "vi" ? "Phép tính nút đã mở" : "Revealed node calculations"}</caption><thead><tr><th>{locale === "vi" ? "Nút" : "Node"}</th><th>{locale === "vi" ? "Các tích" : "Products"}</th><th>Bias</th><th>{locale === "vi" ? "Tổng" : "Sum"}</th><th>{locale === "vi" ? "Kích hoạt" : "Activation"}</th></tr></thead><tbody>{current.after.nodeCalculations.map(calculation => <tr key={calculation.nodeId}><th scope="row">{calculation.nodeId}</th><td>{calculation.contributions.map(item => `${item.sourceValue}×${item.weight}=${item.contribution}`).join("; ")}</td><td>{calculation.bias}</td><td>{calculation.weightedSum}</td><td>{calculation.activation === "relu" ? "ReLU" : (locale === "vi" ? "đồng nhất" : "identity")} → {calculation.activationOutput}</td></tr>)}</tbody></table></div></details>
      </>;
    }}</Frame>
  </div>;
}

function BackpropWorkbench({ locale }: { readonly locale: Locale }) {
  const [scenario, setScenario] = useState<"bp01" | "bp02">("bp01"), [index, setIndex] = useState(0); const trace = backpropagationTrace(scenario); const step = trace.steps[index] ?? trace.steps[0]; const state = step.after;
  const reset = () => { setScenario("bp01"); setIndex(0); };
  const directionText = (direction: "forward" | "backward" | "compare") => locale === "vi" ? direction === "forward" ? "xuôi" : direction === "backward" ? "ngược" : "so sánh" : direction;
  const exactError = (value: number | null) => value === null ? "—" : String(value);
  return <div className={styles.workbench} data-visual-kind="backpropagation" data-scenario={scenario} data-result={state.errorReduced === null ? "pending" : state.errorReduced ? "correct" : "incorrect"}>
    <div className={styles.setup}><SelectField scenario label={locale === "vi" ? "Fixture cập nhật" : "Update fixture"} value={scenario} onChange={value => { setScenario(value as "bp01" | "bp02"); setIndex(0); }}><option value="bp01">BP01 · x=2, target=1</option><option value="bp02">BP02 · x=1, target=0</option></SelectField><div className={styles.setupFact}><b>{locale === "vi" ? "Quy tắc đồ chơi đã công bố" : "Declared toy rule"}</b><span>w′ = w + η × error × input · {locale === "vi" ? "không có bias" : "no bias"}</span></div></div>
    <Boundary locale={locale}>{locale === "vi" ? "Một trọng số tuyến tính được cập nhật một lần để nhìn rõ hướng hiệu chỉnh. Đây không phải toàn bộ backpropagation của mạng nhiều lớp." : "One linear weight is updated once so the correction direction is visible. This is not a complete multilayer backpropagation system."}</Boundary>
    <Legend locale={locale} items={[{ state: "active", en: "Current stage", vi: "Giai đoạn hiện tại" }, { state: "updated", en: "Updated value", vi: "Giá trị đã cập nhật" }, { state: "eliminated", en: "Old error", vi: "Sai số cũ" }]} />
    <Frame steps={trace.steps} index={index} setIndex={setIndex} reset={reset} locale={locale} digest={value => `${locale === "vi" ? "lượt" : "iteration"}=${value.iteration}; ${locale === "vi" ? "hướng" : "direction"}=${directionText(value.direction)}; x=${value.input}; target=${value.target}; w=${value.oldWeight}→${displayNumber(value.newWeight)}; prediction=${displayNumber(value.oldPrediction)}→${displayNumber(value.newPrediction)}; error=${exactError(value.oldError)}→${exactError(value.newError)}; error²=${exactError(value.oldSquaredError)}→${exactError(value.newSquaredError)}`}>{current => <>
      <div className={styles.iterationRail} data-training-iteration={state.iteration}><div data-state={state.iteration === 1 ? "active" : "updated"}><span>{locale === "vi" ? "Lượt huấn luyện 1" : "Training iteration 1"}</span><strong>w={state.oldWeight}</strong></div><b aria-hidden="true">→</b><div data-state={state.iteration === 2 ? "active" : "unvisited"}><span>{locale === "vi" ? "Lượt huấn luyện 2" : "Training iteration 2"}</span><strong>w={displayNumber(state.newWeight)}</strong></div></div>
      <section className={styles.directionRail} data-direction={state.direction} aria-label={locale === "vi" ? "Hướng truyền tín hiệu và hiệu chỉnh" : "Signal and correction directions"}><h3>{locale === "vi" ? "Hai hướng khác nhau" : "Two distinct directions"}</h3><div data-flow="forward" data-state={state.direction === "forward" ? "active" : "updated"}><span>{locale === "vi" ? "Tín hiệu xuôi" : "Forward signal"}</span><strong>{locale === "vi" ? "đầu vào" : "input"} x={state.input}</strong><b aria-hidden="true">→</b><strong>{locale === "vi" ? "trọng số đã chọn" : "selected weight"} w={state.iteration === 2 ? displayNumber(state.newWeight) : state.oldWeight}</strong><b aria-hidden="true">→</b><strong>{locale === "vi" ? "đầu ra" : "output"} ŷ={state.iteration === 2 ? displayNumber(state.newPrediction) : displayNumber(state.oldPrediction)}</strong></div><div data-flow="backward" data-state={state.direction === "backward" ? "active" : state.oldError !== null ? "updated" : "unvisited"}><span>{locale === "vi" ? "Hiệu chỉnh ngược" : "Backward correction"}</span><strong>{locale === "vi" ? "trọng số đã chọn" : "selected weight"}</strong><b aria-hidden="true">←</b><strong>{locale === "vi" ? "sai số tại đầu ra" : "error at output"}={exactError(state.oldError)}</strong></div></section>
      <div className={styles.cycle} data-direction={state.direction}><div data-state={state.direction === "forward" ? "active" : "updated"}><span>1 · {locale === "vi" ? "Lan truyền xuôi" : "Forward"}</span><strong>x {state.input} × w {state.oldWeight} = ŷ {displayNumber(state.oldPrediction)}</strong></div><b aria-hidden="true">→</b><div data-state={state.direction === "compare" ? "active" : state.oldPrediction !== null ? "updated" : "unvisited"}><span>2 · {locale === "vi" ? "So sánh" : "Compare"}</span><strong>target {state.target} − ŷ {displayNumber(state.oldPrediction)} = error {displayNumber(state.oldError)}</strong></div><b aria-hidden="true">↘</b><div data-state={state.direction === "backward" ? "active" : state.oldError !== null ? "updated" : "unvisited"}><span>3 · {locale === "vi" ? "Truyền ngược" : "Backward"}</span><strong>Δw = η {state.learningRate} × {displayNumber(state.oldError)} × {state.input}</strong></div><b aria-hidden="true">→</b><div data-state={state.newWeight !== null ? "updated" : "unvisited"}><span>4 · {locale === "vi" ? "Cập nhật" : "Update"}</span><strong>w {state.oldWeight} → {displayNumber(state.newWeight)}</strong></div></div>
      <div className={styles.beforeAfter} data-backprop-before-after><div><span>{locale === "vi" ? "Lượt 1 · trước cập nhật" : "Iteration 1 · before update"}</span><strong>ŷ {displayNumber(state.oldPrediction)}</strong><small>error {exactError(state.oldError)}</small><small>error² {exactError(state.oldSquaredError)}</small></div><div data-state={state.newSquaredError !== null ? "updated" : "unvisited"}><span>{locale === "vi" ? "Lượt 2 · sau một cập nhật" : "Iteration 2 · after one update"}</span><strong>ŷ {displayNumber(state.newPrediction)}</strong><small>error {exactError(state.newError)}</small><small>error² {exactError(state.newSquaredError)}</small></div></div>
      <div className={styles.feedback} role="status" aria-live="polite" data-feedback={state.errorReduced === null ? "pending" : state.errorReduced ? "correct" : "incorrect"}><strong>{state.errorReduced === null ? (locale === "vi" ? "Chưa có so sánh sau cập nhật" : "After-update comparison not reached") : state.errorReduced ? (locale === "vi" ? "Sai số bình phương đã giảm trong fixture này." : "Squared error decreased in this fixture.") : (locale === "vi" ? "Sai số không giảm; xem lại quy tắc đã công bố." : "Error did not decrease; revisit the declared rule.")}</strong></div>
      <details className={styles.readback} data-backprop-fallback><summary>{locale === "vi" ? "Đọc toàn bộ lượt, hướng và sai số dạng bảng" : "Read every iteration, direction and error as a table"}</summary><div className={styles.tableScroll} role="region" tabIndex={0} aria-label={locale === "vi" ? "Bảng trạng thái lan truyền ngược" : "Backpropagation state table"}><table><caption>{locale === "vi" ? "Dấu gạch ngang nghĩa là giá trị chưa được mở ở bước đó." : "A dash means the value has not been revealed at that step."}</caption><thead><tr><th>{locale === "vi" ? "Bước" : "Step"}</th><th>{locale === "vi" ? "Lượt" : "Iteration"}</th><th>{locale === "vi" ? "Hướng" : "Direction"}</th><th>ŷ1</th><th>error1</th><th>error1²</th><th>ŷ2</th><th>error2</th><th>error2²</th></tr></thead><tbody>{trace.steps.map(item => <tr key={item.id} data-backprop-step={item.id}><th scope="row">{t(item.title, locale)}</th><td>{item.after.iteration}</td><td>{directionText(item.after.direction)}</td><td>{displayNumber(item.after.oldPrediction)}</td><td>{exactError(item.after.oldError)}</td><td>{exactError(item.after.oldSquaredError)}</td><td>{displayNumber(item.after.newPrediction)}</td><td>{exactError(item.after.newError)}</td><td>{exactError(item.after.newSquaredError)}</td></tr>)}</tbody></table></div></details>
    </>}</Frame>
  </div>;
}

function RegressionWorkbench({ locale }: { readonly locale: Locale }) {
  const [predictionX, setPredictionX] = useState(3.5), [pointPreset, setPointPreset] = useState<RegressionPointPreset>("baseline"), [index, setIndex] = useState(0); const trace = regressionTrace("energy", predictionX, pointPreset); const step = trace.steps[index] ?? trace.steps[0], state = step.after;
  const reset = () => { setPredictionX(3.5); setPointPreset("baseline"); setIndex(0); };
  const titleId = useId(), descId = useId(), axisMarkerId = `${titleId.replace(/:/g, "")}-axis-arrow`; const sx = (x: number) => 12 + x * 12; const sy = (y: number) => 88 - y * 5;
  const predictionScenario = predictionX === 3.5 ? "interpolation" : predictionX === 6 ? "extrapolation" : "custom";
  return <div className={styles.workbench} data-visual-kind="regression" data-scenario="energy" data-result={index === trace.steps.length - 1 ? "prediction" : "pending"}>
    <div className={styles.setup}><SelectField scenario label={locale === "vi" ? "Ca dự đoán" : "Prediction scenario"} value={predictionScenario} onChange={value => { if (value !== "custom") setPredictionX(value === "extrapolation" ? 6 : 3.5); setIndex(0); }}><option value="interpolation">{locale === "vi" ? "Nội suy · x=3.5" : "Interpolation · x=3.5"}</option><option value="extrapolation">{locale === "vi" ? "Ngoại suy · x=6" : "Extrapolation · x=6"}</option>{predictionScenario === "custom" && <option value="custom">{locale === "vi" ? `Tùy chỉnh · x=${predictionX}` : `Custom · x=${predictionX}`}</option>}</SelectField><div data-regression-preset-control><SelectField label={locale === "vi" ? "Bộ điểm huấn luyện có kiểm soát" : "Controlled training-point preset"} value={pointPreset} onChange={value => { setPointPreset(value as RegressionPointPreset); setIndex(0); }}><option value="baseline">{locale === "vi" ? "Cơ sở · 4 điểm" : "Baseline · 4 points"}</option><option value="moved">{locale === "vi" ? "Di chuyển P4: (4,10) → (4,8)" : "Move P4: (4,10) → (4,8)"}</option><option value="added">{locale === "vi" ? "Thêm P5: (5,12)" : "Add P5: (5,12)"}</option></SelectField></div><div className={styles.field}><label htmlFor={`${titleId}-x`}>{locale === "vi" ? "x cần dự đoán (giới hạn 0–7)" : "Prediction x (clamped to 0–7)"}</label><input id={`${titleId}-x`} type="number" min="0" max="7" step="0.5" value={predictionX} onChange={event => { const value = Number(event.target.value); if (Number.isFinite(value)) { setPredictionX(Math.min(7, Math.max(0, value))); setIndex(0); } }} /></div></div>
    <Boundary locale={locale}>{locale === "vi" ? `Đường OLS và phần dư được tính lại từ ${trace.final.points.length} cặp trong bộ điểm đang chọn. Mô hình minh họa hồi quy có giám sát và đầu ra liên tục; dự đoán ngoài miền x=${trace.final.observedRange[0]}…${trace.final.observedRange[1]} là ngoại suy.` : `The OLS line and residuals are recalculated from the ${trace.final.points.length} pairs in the selected preset. The model demonstrates supervised regression with continuous output; predictions outside x=${trace.final.observedRange[0]}…${trace.final.observedRange[1]} are extrapolations.`}</Boundary>
    <Frame steps={trace.steps} index={index} setIndex={setIndex} reset={reset} locale={locale} digest={value => `${locale === "vi" ? "giai đoạn" : "stage"}=${value.stage}; preset=${value.pointPreset}; changedPointId=${value.changedPointId ?? "—"}; previousFit=${value.previousFit ? `y=${value.previousFit.slope}x+${value.previousFit.intercept},SSE=${value.previousFit.sse}` : "—"}; points=${value.points.map(point => `${point.x},${point.y}`).join("|")}; y=${displayNumber(value.slope)}x+${displayNumber(value.intercept)}; SSE=${displayNumber(value.sse)}; x=${value.predictionX}; y=${displayNumber(value.predictionY)}; ${locale === "vi" ? "ngoại suy" : "extrapolation"}=${yesNo(value.extrapolation, locale)}`}>{current => {
      const fitVisible = state.slope !== null && state.intercept !== null;
      const predictionVisible = state.predictionY !== null;
      const rangeText = `${state.observedRange[0]}≤x≤${state.observedRange[1]}`;
      const residualText = state.residuals.length ? state.residuals.map((value, pointIndex) => `P${pointIndex + 1}:${displayNumber(value)}`).join(", ") : (locale === "vi" ? "chưa mở" : "not revealed");
      const changeDescription = state.changedPointId ? (locale === "vi" ? `${state.changedPointId} là điểm thay đổi trong preset này.` : `${state.changedPointId} is the changed point in this preset.`) : (locale === "vi" ? "Không có điểm nào thay đổi trong preset cơ sở." : "No point is changed in the baseline preset.");
      const dynamicDescription = locale === "vi" ? `${state.points.length} điểm huấn luyện. ${changeDescription} Miền huấn luyện ${rangeText}; hai vùng còn lại là ngoại suy. Phương trình ${fitVisible ? `y=${state.slope}x+${state.intercept}` : "chưa mở"}; phần dư ${residualText}; dự đoán tại x=${state.predictionX} ${predictionVisible ? `là ${state.predictionY}, ${state.extrapolation ? "ngoài" : "trong"} miền huấn luyện` : "chưa mở"}.` : `${state.points.length} training points. ${changeDescription} The training region is ${rangeText}; both outer regions are extrapolation. Equation ${fitVisible ? `y=${state.slope}x+${state.intercept}` : "not revealed"}; residuals ${residualText}; prediction at x=${state.predictionX} ${predictionVisible ? `is ${state.predictionY} and lies ${state.extrapolation ? "outside" : "inside"} the training region` : "is not revealed"}.`;
      return <>
      <div className={styles.split}><figure className={styles.chartFigure}><svg viewBox="0 0 100 100" role="img" aria-labelledby={`${titleId} ${descId}`}><title id={titleId}>{locale === "vi" ? "Biểu đồ hồi quy năng lượng" : "Energy regression chart"}</title><desc id={descId}>{dynamicDescription}</desc><defs><marker id={axisMarkerId} markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path className={styles.axisArrow} d="M0,0 L5,2.5 L0,5 z" /></marker></defs><rect data-regression-region="extrapolation-low" className={styles.extrapolationRegion} x={sx(0)} y="8" width={sx(state.observedRange[0]) - sx(0)} height="82" /><rect data-regression-region="training" className={styles.trainingRegion} x={sx(state.observedRange[0])} y="8" width={sx(state.observedRange[1]) - sx(state.observedRange[0])} height="82" /><rect data-regression-region="extrapolation-high" className={styles.extrapolationRegion} x={sx(state.observedRange[1])} y="8" width={sx(7) - sx(state.observedRange[1])} height="82" /><text className={styles.regionLabel} x={sx((state.observedRange[0] + state.observedRange[1]) / 2)} y="13">{locale === "vi" ? "miền huấn luyện" : "training region"}</text><text className={styles.regionLabel} x={sx(5.8)} y="13">{locale === "vi" ? "ngoại suy" : "extrapolation"}</text><line className={styles.axis} x1="10" y1="90" x2="96" y2="90" markerEnd={`url(#${axisMarkerId})`} /><line className={styles.axis} x1="10" y1="90" x2="10" y2="8" markerEnd={`url(#${axisMarkerId})`} />{[0, 1, 2, 3, 4, 5, 6, 7].map(value => <g key={`x-tick-${value}`} data-axis-tick="x"><line className={styles.tickMark} x1={sx(value)} y1="88.5" x2={sx(value)} y2="91.5" /><text className={styles.tickLabel} x={sx(value)} y="95">{value}</text></g>)}{[0, 5, 10, 15].map(value => <g key={`y-tick-${value}`} data-axis-tick="y"><line className={styles.tickMark} x1="8.5" y1={sy(value)} x2="11.5" y2={sy(value)} /><text className={styles.tickLabel} x="7" y={sy(value) + 1}>{value}</text></g>)}{fitVisible && <line className={styles.fitLine} x1={sx(0)} y1={sy(state.intercept!)} x2={sx(7)} y2={sy(state.slope! * 7 + state.intercept!)} />}{fitVisible && state.points.map((point, pointIndex) => <g key={`residual-${pointIndex}`} data-residual-id={`p${pointIndex + 1}`}><line className={styles.residualLine} x1={sx(point.x)} y1={sy(point.y)} x2={sx(point.x)} y2={sy(state.fittedValues[pointIndex])} /><text className={styles.residualLabel} x={sx(point.x) + 1} y={(sy(point.y) + sy(state.fittedValues[pointIndex])) / 2}>r{pointIndex + 1}</text></g>)}{state.points.map((point, pointIndex) => { const pointId = `P${pointIndex + 1}`; const changed = state.changedPointId === pointId; return <g key={pointIndex} data-point-id={pointId.toLowerCase()} data-point-state={changed ? "changed" : "unchanged"}>{changed && <circle className={styles.changedPointRing} data-changed-point-id={pointId} cx={sx(point.x)} cy={sy(point.y)} r="5.4" />}<circle cx={sx(point.x)} cy={sy(point.y)} r="3.4" /><text x={sx(point.x) + 2} y={sy(point.y) - 3}>({point.x},{point.y})</text>{changed && <text className={styles.changedPointLabel} x={sx(point.x) + 2} y={sy(point.y) + 6}>{locale === "vi" ? `${pointId} đã thay đổi` : `${pointId} changed`}</text>}</g>; })}{predictionVisible && <g data-point-id="prediction" data-state="active"><line className={styles.guide} x1={sx(state.predictionX)} y1="90" x2={sx(state.predictionX)} y2={sy(state.predictionY!)} /><circle cx={sx(state.predictionX)} cy={sy(state.predictionY!)} r="4" /><text x={sx(state.predictionX) + 2} y={sy(state.predictionY!) - 3}>ŷ {state.predictionY}</text></g>}<text className={styles.axisLabel} x="75" y="99">{locale === "vi" ? "đầu vào x" : "input x"}</text><text className={styles.axisLabel} x="12" y="6">{locale === "vi" ? "mục tiêu liên tục y" : "continuous target y"}</text></svg><figcaption>{locale === "vi" ? "Vùng nền phân biệt miền huấn luyện với ngoại suy; mỗi đoạn đứt có nhãn r là một phần dư y−ŷ; vòng đôi đánh dấu điểm thay đổi." : "Background regions separate training from extrapolation; each dashed segment labelled r is a residual y−ŷ; a double ring marks the changed point."}</figcaption></figure>
        <div className={styles.evidence}><div><span>{locale === "vi" ? "Phương trình" : "Equation"}</span><strong>{fitVisible ? `y = ${state.slope}x + ${state.intercept}` : (locale === "vi" ? "Chưa khớp mô hình" : "Model not fitted yet")}</strong></div><div><span>SSE</span><strong>{displayNumber(state.sse)}</strong></div><div><span>{locale === "vi" ? "Dự đoán liên tục" : "Continuous prediction"}</span><strong>x {state.predictionX} → ŷ {displayNumber(state.predictionY)}</strong></div><div data-decision={state.extrapolation ? "rejected-higher" : "accepted"}><span>{locale === "vi" ? "Miền" : "Range status"}</span><strong>{state.extrapolation ? (locale === "vi" ? "Ngoại suy — thận trọng" : "Extrapolation — use caution") : (locale === "vi" ? "Nội suy trong miền huấn luyện" : "Interpolation within training range")}</strong></div></div></div>
      {state.previousFit && <section className={styles.fitChange} data-regression-fit-change><h3>{locale === "vi" ? `${state.changedPointId} thay đổi dữ liệu nên mô hình được khớp lại` : `${state.changedPointId} changes the data, so the model is refitted`}</h3><div><article><span>{locale === "vi" ? "Trước · preset cơ sở" : "Before · baseline preset"}</span><strong>y={state.previousFit.slope}x+{state.previousFit.intercept}</strong><small>SSE={state.previousFit.sse}</small></article><b aria-hidden="true">→</b><article data-state={fitVisible ? "updated" : "unvisited"}><span>{locale === "vi" ? "Sau · preset hiện tại" : "After · current preset"}</span><strong>{fitVisible ? `y=${state.slope}x+${state.intercept}` : "—"}</strong><small>SSE={displayNumber(state.sse)}</small></article></div></section>}
      <section className={styles.regressionComparison} data-regression-comparison><h3>{locale === "vi" ? "So sánh loại đầu ra" : "Compare output types"}</h3><div><article data-model="regression"><span>{locale === "vi" ? "Mô hình hồi quy này" : "This regression model"}</span><strong>{locale === "vi" ? "Đầu ra số liên tục" : "Continuous numeric output"}</strong><p>x={state.predictionX} → ŷ={displayNumber(state.predictionY)}</p></article><article data-model="separate-classifier"><span>{locale === "vi" ? "Một mô hình phân loại riêng (chỉ để đối chiếu)" : "A separate classifier (contrast only)"}</span><strong>{locale === "vi" ? "Đầu ra là nhãn loại" : "Categorical label output"}</strong><p>{locale === "vi" ? "Ví dụ nhãn: «mức dùng cao»; mô hình hồi quy trên không tạo nhãn này." : "Example label: “high use”; the regression model above does not produce this label."}</p></article></div></section>
      <details className={styles.readback} data-state-fallback><summary>{locale === "vi" ? "Đọc dữ liệu, phần dư và đối chiếu dạng bảng" : "Read points, residuals and comparison as tables"}</summary><div className={styles.tableScroll} role="region" tabIndex={0} aria-label={locale === "vi" ? "Bảng hồi quy" : "Regression table"}><table><caption>{locale === "vi" ? "Các cặp huấn luyện và trạng thái phép khớp hiện tại" : "Training pairs and current fit state"}</caption><thead><tr><th>ID</th><th>{locale === "vi" ? "Trạng thái thay đổi" : "Change state"}</th><th>x</th><th>y</th><th>ŷ</th><th>{locale === "vi" ? "Phần dư y−ŷ" : "Residual y−ŷ"}</th></tr></thead><tbody>{state.points.map((point, pointIndex) => { const pointId = `P${pointIndex + 1}`; const changed = state.changedPointId === pointId; const changeState = changed ? state.pointPreset === "moved" ? (locale === "vi" ? "Đã di chuyển từ (4,10)" : "Moved from (4,10)") : (locale === "vi" ? "Điểm mới được thêm" : "Newly added point") : (locale === "vi" ? "Không đổi" : "Unchanged"); return <tr key={pointIndex} data-fallback-step={pointId.toLowerCase()} data-point-state={changed ? "changed" : "unchanged"}><th scope="row">{pointId}</th><td>{changeState}</td><td>{point.x}</td><td>{point.y}</td><td>{displayNumber(state.fittedValues[pointIndex] ?? null)}</td><td>{displayNumber(state.residuals[pointIndex] ?? null)}</td></tr>; })}</tbody></table><table data-regression-comparison-fallback><caption>{locale === "vi" ? "Đối chiếu đầu ra — hai loại mô hình riêng" : "Output comparison — two separate model types"}</caption><thead><tr><th>{locale === "vi" ? "Mô hình" : "Model"}</th><th>{locale === "vi" ? "Kiểu đầu ra" : "Output type"}</th><th>{locale === "vi" ? "Kết quả minh họa" : "Illustrative result"}</th></tr></thead><tbody><tr><th scope="row">{locale === "vi" ? "Hồi quy đang chạy" : "Current regression"}</th><td>{locale === "vi" ? "Số liên tục" : "Continuous number"}</td><td>ŷ={displayNumber(state.predictionY)}</td></tr><tr><th scope="row">{locale === "vi" ? "Bộ phân loại riêng (đối chiếu)" : "Separate classifier (contrast)"}</th><td>{locale === "vi" ? "Nhãn loại" : "Category label"}</td><td>{locale === "vi" ? "«mức dùng cao» — không phải đầu ra của mô hình hồi quy" : "“high use” — not output by the regression model"}</td></tr></tbody></table></div></details>
      </>;
    }}</Frame>
  </div>;
}

export function Section18AIWorkbench({ kind, locale }: { readonly kind: AIVisualKind; readonly locale: Locale }) {
  if (kind === "dijkstra-search") return <DijkstraWorkbench locale={locale} />;
  if (kind === "astar-search") return <AStarWorkbench locale={locale} />;
  if (kind === "learning-categories") return <LearningWorkbench locale={locale} />;
  if (kind === "neural-network") return <NeuralWorkbench locale={locale} />;
  if (kind === "backpropagation") return <BackpropWorkbench locale={locale} />;
  return <RegressionWorkbench locale={locale} />;
}

export type { AIVisualKind };
